package com.fincore.fincore.exception; import java.time.Instant; import java.util.*; import org.springframework.http.*; import org.springframework.security.authentication.BadCredentialsException; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import jakarta.servlet.http.HttpServletRequest; @RestControllerAdvice public class GlobalExceptionHandler{private ResponseEntity<ApiError> e(HttpStatus s,String m,HttpServletRequest r,Map<String,String> v){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI(),v));}@ExceptionHandler(NotFoundException.class)ResponseEntity<ApiError> nf(NotFoundException x,HttpServletRequest r){return e(HttpStatus.NOT_FOUND,x.getMessage(),r,null);}@ExceptionHandler(ConflictException.class)ResponseEntity<ApiError> cf(ConflictException x,HttpServletRequest r){return e(HttpStatus.CONFLICT,x.getMessage(),r,null);}@ExceptionHandler(BadRequestException.class)ResponseEntity<ApiError> br(BadRequestException x,HttpServletRequest r){return e(HttpStatus.BAD_REQUEST,x.getMessage(),r,null);}@ExceptionHandler(ForbiddenException.class)ResponseEntity<ApiError> fb(ForbiddenException x,HttpServletRequest r){return e(HttpStatus.FORBIDDEN,x.getMessage(),r,null);}@ExceptionHandler(BadCredentialsException.class)ResponseEntity<ApiError> bc(BadCredentialsException x,HttpServletRequest r){return e(HttpStatus.UNAUTHORIZED,"Invalid email or password",r,null);}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError> val(MethodArgumentNotValidException x,HttpServletRequest r){Map<String,String> m=new LinkedHashMap<>();x.getBindingResult().getFieldErrors().forEach(f->m.putIfAbsent(f.getField(),f.getDefaultMessage()));return e(HttpStatus.BAD_REQUEST,"Validation failed",r,m);}@ExceptionHandler(Exception.class)ResponseEntity<ApiError> any(Exception x,HttpServletRequest r){return e(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r,null);}}
